begin;
with j as (select * from jsonb_to_recordset($law7d0050$[{"code_id":"NK_RF","article_number":"105.16-4","version_date":"2000-07-31","article_text":"1. Глобальная документация за отчетный период составляется в произвольной форме и должна содержать:\n\n1) информацию о структуре участия в капитале и об осуществлении контроля международной группы компаний, а также информацию о рынках товаров (работ, услуг), на которых участники международной группы компаний осуществляют свою основную деятельность (в виде схем);\n\n2) информацию о деятельности международной группы компаний:\n\nописание основных факторов, влияющих на финансовый результат международной группы компаний;\n\nописание последовательности движения поставок в отношении крупнейших по показателю дохода (выручки) международной группы компаний пяти товаров (работ, услуг), а также последовательности движения поставок иных товаров (работ, услуг) и другой деятельности, которые формируют более 5 процентов дохода (выручки) международной группы компаний за отчетный период, и основных географических мест расположения рынков товаров (работ, услуг), на которых реализуются (выполняются, оказываются) указанные товары (работы, услуги);\n\nперечень и краткое описание существенных договоров оказания услуг, заключенных между участниками международной группы компаний (за исключением договоров на осуществление научно-исследовательских и опытно-конструкторских работ), включая описание функциональных возможностей основных участников международной группы компаний, вовлеченных в оказание данных услуг, и подходов к ценообразованию в рамках оказываемых услуг внутри международной группы компаний;\n\nкраткий функциональный анализ участников международной группы компаний, оказывающих влияние на финансовый результат этой группы, в том числе описание основных выполняемых функций, используемых активов, принимаемых экономических (коммерческих) рисков;\n\nинформацию о существенных сделках, связанных с реструктуризацией деятельности в рамках международной группы компаний, приобретении и отчуждении активов в отчетном периоде;\n\n3) информацию о нематериальных активах международной группы компаний:\n\nописание стратегии развития международной группы компаний в отношении разработки, владения и использования нематериальных активов, в том числе размещения основных научно-исследовательских центров и расположения органов управления ими;\n\nописание нематериальных активов (групп нематериальных активов), оказывающих существенное влияние на методику ценообразования в сделках (операциях) между участниками международной группы компаний, и перечень участников международной группы компаний, владеющих такими активами;\n\nперечень существенных договоров, связанных с нематериальными активами, заключенных между участниками международной группы компаний;\n\nобщее описание методик ценообразования по сделкам между участниками международной группы компаний, связанным с разработкой, владением и использованием нематериальных активов;\n\nобщее описание сделок (операций) по передаче прав на нематериальные активы между участниками международной группы компаний в отчетном периоде с указанием таких участников и уровня вознаграждения, связанного с такой передачей;\n\n4) информацию о финансовой деятельности в международной группе компаний:\n\nкраткую информацию о системе финансирования международной группы компаний (включая информацию о финансировании, привлеченном от лиц, не являющихся участниками международной группы компаний);\n\nуказание участников международной группы компаний, которые выполняют основные функции финансирования в международной группе компаний, в том числе государств (территорий), являющихся местом регистрации таких участников и (или) местом их управления;\n\nобщее описание методик ценообразования между участниками международной группы компаний по сделкам, связанным с финансированием участников международной группы компаний;\n\n5) иную информацию:\n\nконсолидированную финансовую отчетность за последний отчетный период или при ее отсутствии иную консолидированную отчетность за последний отчетный период, подготовленную для управленческих, налоговых и иных целей;\n\nперечень и краткое описание соглашений о ценообразовании, налоговых разъяснений компетентных органов иностранных государств (территорий), в подготовке которых не участвовал федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, применяемых в сделках между участниками международной группы компаний и связанных с распределением доходов между государствами (территориями).\n\n2. При обнаружении налогоплательщиком в представленной глобальной документации неполноты сведений, неточностей либо ошибок в ее заполнении налогоплательщик вправе представить уточненную глобальную документацию.\n\n3. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-4. Глобальная документация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e048f1c7cec9264e8a2d4a8895b2b3c94bf7a3912cd955a4bbcdc4a3be9a539"},{"code_id":"NK_RF","article_number":"105.16-5","version_date":"2000-07-31","article_text":"1. Национальной документацией признается документация, составленная в произвольной форме участником международной группы компаний в отношении контролируемой сделки (группы однородных сделок), одной из сторон и (или) выгодоприобретателем которой является другой участник такой международной группы компаний, местом регистрации, либо местом жительства, либо местом налогового резидентства которого не является Российская Федерация, и содержащая информацию, предусмотренную пунктом 1 статьи 10515 настоящего Кодекса.\n\n2. В случае, если национальная документация предполагает раскрытие информации, представленной в отношении того же отчетного периода в соответствии со статьей 10516-4 настоящего Кодекса в составе глобальной документации, повторное представление информации не требуется при условии наличия в национальной документации указания на пункты глобальной документации, содержащие необходимую информацию.\n\n3. Налогоплательщик вправе представить иную информацию, подтверждающую, что коммерческие и (или) финансовые условия контролируемых сделок соответствуют тем, которые имели место в сопоставимых сделках, с учетом произведенных корректировок для обеспечения сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок, сторонами которых являются лица, не признаваемые взаимозависимыми, с условиями контролируемой сделки.\n\n4. При обнаружении налогоплательщиком в представленной национальной документации неполноты сведений, неточностей либо ошибок в ее заполнении налогоплательщик вправе представить уточненную национальную документацию.\n\n5. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-5. Национальная документация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72bdbbb39293480e7f19c527ea55c9e5fbeab28a5548071861331e141a36b74d"},{"code_id":"NK_RF","article_number":"105.16-6","version_date":"2000-07-31","article_text":"1. Страновой отчет должен содержать информацию:\n\n1) об общей сумме доходов (выручки) по сделкам за отчетный период, в том числе с разбивкой на сумму доходов (выручки) по сделкам с участниками этой международной группы компаний и сумму доходов (выручки) по сделкам с другими лицами, в том числе ассоциированными организациями;\n\n2) о сумме прибыли (убытка) до налогообложения за отчетный период;\n\n3) о сумме исчисленного налога на прибыль организаций (налога с дохода (прибыли) или его аналога) за отчетный период;\n\n4) о сумме уплаченного налога на прибыль организаций (налога с дохода (прибыли) или его аналога) в отчетном периоде;\n\n5) о размере капитала на дату окончания отчетного периода;\n\n6) о сумме накопленной прибыли на дату окончания отчетного периода;\n\n7) о численности работников за отчетный период;\n\n8) о величине материальных активов на дату окончания отчетного периода;\n\n9) идентификационные сведения о каждом участнике международной группы, в том числе с указанием государства (территории), в соответствии с правом которого такой участник учрежден, государства (территории) налогового резидентства и основных видов деятельности каждого участника международной группы компаний.\n\n2. Требования к составу информации, предусмотренной пунктом 1 настоящей статьи, определяются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в порядке заполнения странового отчета, предусмотренном пунктом 4 статьи 10516-3 настоящего Кодекса.\n\n3. Информация, предусмотренная подпунктами 1 - 8 пункта 1 настоящей статьи, отражается в обобщенном виде в отношении деятельности участников международной группы компаний, являющихся налоговыми резидентами и (или) постоянными представительствами в одном государстве (территории), без разделения информации по отдельным участникам международной группы компаний.\n\nИнформация, предусмотренная подпунктами 1 - 8 пункта 1 настоящей статьи, отражается на основании данных консолидированной финансовой отчетности, составляемой материнской компанией международной группы компаний в соответствии с Международными стандартами финансовой отчетности или иными международно признанными стандартами составления финансовой отчетности, либо на основании данных бухгалтерского и (или) налогового учета, формируемых исходя из правил, принятых в государстве (территории) налогового резидентства соответствующего участника международной группы компаний, либо на основании иной информации, обеспечивающей полноту и достоверность сведений странового отчета. При этом налогоплательщик также обеспечивает ежегодное последовательное использование одних и тех же источников информации для заполнения соответствующих показателей, а при их изменении раскрытие причин такого изменения.\n\nНалогоплательщик, являющийся участником международной группы компаний, вправе раскрыть методологию и принципы составления странового отчета, а также представить иную дополнительную информацию, которая содержит детальные сведения в отношении информации, представленной в обязательном порядке в соответствии с пунктом 1 настоящей статьи.\n\n4. При обнаружении налогоплательщиком в страновом отчете неполноты сведений, неточностей либо ошибок в его заполнении налогоплательщик вправе представить уточненный страновой отчет.\n\nВ случае представления уточненного странового отчета до момента, когда налогоплательщик узнал об установлении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или территориальным налоговым органом факта отражения в страновом отчете недостоверных сведений, такой налогоплательщик освобождается от ответственности, предусмотренной статьей 12910 настоящего Кодекса.","article_title":"Статья 105.16-6. Страновой отчет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e9514ef053b2be28d10df3817c7f17116cf6505148f3f34c4756e0282c38fc0"},{"code_id":"NK_RF","article_number":"105.16-7","version_date":"2000-07-31","article_text":"1. В случае, если хотя бы один участник международной группы компаний, более 50 процентов активов которой по состоянию на последнюю отчетную дату, предшествующую году совершения таким участником контролируемых сделок, находится на территории Российской Федерации, совершил сделки в области внешней торговли, которые признаются контролируемыми и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса, материнская компания такой международной группы компаний или уполномоченный участник такой международной группы компаний, которые являются российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, обязаны представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения из консолидированной финансовой отчетности такой международной группы компаний, финансовой отчетности участников такой международной группы компаний, совершивших такие сделки и (или) сделки по последующей реализации указанных товаров и (или) обеспечивавших совершение указанных сделок (в том числе путем оказания услуг по перевозке, хранению, упаковке, страхованию, финансированию, маркетингу), в порядке и сроки, которые установлены настоящей статьей.\n\n2. Сведения из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участников международной группы компаний, указанные в пункте 1 настоящей статьи, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в электронной форме по установленным форматам в срок не позднее двенадцати месяцев с даты окончания финансового года, в котором были совершены сделки, указанные в пункте 1 настоящей статьи.\n\n3. Форматы представления сведений из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участников международной группы компаний в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n4. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе в порядке, определенном пунктом 2 статьи 931 настоящего Кодекса, истребовать у материнской компании международной группы компаний или уполномоченного участника международной группы компаний, которые являются российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, документы и (или) информацию о сделках, указанных в пункте 1 настоящей статьи, об участниках международной группы компаний, обеспечивавших совершение указанных сделок (в том числе путем оказания услуг по перевозке, хранению, упаковке, страхованию, финансированию, маркетингу).\n\n(Дополнение статьей - Федеральный закон от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.16-7. Обязанность по представлению сведений из консолидированной финансовой отчетности международной группы компаний и финансовой отчетности участников международной группы компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38ab9280ebac187e05682bbe8a2da9aed3f1d9ebf139b716bbe7a519337d4b94"},{"code_id":"NK_RF","article_number":"105.17","version_date":"2000-07-31","article_text":"1. Проверка полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами (далее в настоящей главе - п\n\nроверка) проводится федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по месту его нахождения.\n\nПроверка проводится на основании уведомления о контролируемых сделках или извещения территориального налогового органа, направленных в соответствии со статьей 10516 настоящего Кодекса, а также при выявлении контролируемой сделки в результате проведения федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, повторной выездной налоговой проверки в порядке контроля за деятельностью налогового органа, проводившего налоговую проверку, налоговый мониторинг. (В редакции федеральных законов от 04.11.2014 № 348-ФЗ, от 17.02.2021 № 6-ФЗ)\n\nРешение о проведении проверки не может быть принято в отношении совершенной налогоплательщиком в календарном году контролируемой сделки, по которой такой налогоплательщик обратился в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о заключении соглашения о ценообразовании для целей налогообложения за тот же календарный год в порядке, предусмотренном главой 146 настоящего Кодекса, в случае, если федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, не принято ни одно из решений, предусмотренных подпунктами 1 и 2 пункта 5 статьи 10522 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nПри проведении проверок федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе проводить мероприятия налогового контроля, установленные статьями 95 - 97 настоящего Кодекса. При этом контроль соответствия цен, примененных в контролируемых сделках, рыночным ценам не может быть предметом выездных и камеральных проверок.\n\nВ случае представления налогоплательщиком уточненной налоговой декларации, в которой сумма налога, исчисленная в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, отражена в меньшем размере (сумма убытка в большем размере), чем ранее заявленная, решение о проведении проверки может быть вынесено не позднее двух лет со дня представления указанной уточненной налоговой декларации. При этом проверка проводится только в отношении контролируемой сделки, по которой произведена корректировка в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nВ случае представления налогоплательщиком заявления о заключении соглашения о ценообразовании для целей налогообложения в соответствии с пунктом 1 статьи 10519 настоящего Кодекса, по результатам рассмотрения которого федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, принято решение, предусмотренное подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса, решение о проведении проверки в отношении контролируемой сделки, которая являлась предметом рассмотрения заявления налогоплательщика о заключении соглашения о ценообразовании для целей налогообложения, может быть вынесено не позднее двух лет со дня принятия решения, предусмотренного подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nТечение срока, предусмотренного абзацем третьим настоящего пункта, приостанавливается при получении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, информации об обжаловании в судебном порядке решения, предусмотренного подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса. Такое приостановление действует до дня вступления в законную силу соответствующего судебного акта. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе проводить две и более проверки в отношении одной контролируемой сделки (группы однородных сделок) за один и тот же календарный год, если иное не предусмотрено настоящим пунктом.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе проводить в отношении одной контролируемой сделки (группы однородных сделок) повторные проверки в случае представления налогоплательщиком уточненной налоговой декларации, в которой отражена сумма налога в меньшем размере (сумма убытка в большем размере), чем ранее заявленная в налоговой декларации, представленной в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nВ случае, если у налогоплательщика, являющегося стороной контролируемой сделки (группы однородных сделок), в отношении указанной сделки (группы однородных сделок) за календарный год была осуществлена проверка в соответствии с настоящей статьей и по результатам такой проверки было установлено соответствие условий контролируемой сделки (группы однородных сделок) условиям сделок между лицами, не являющимися взаимозависимыми, в отношении указанной сделки (группы однородных сделок) не могут быть осуществлены проверки у налогоплательщиков, являющихся другими сторонами указанной сделки (группы однородных сделок).\n\nПри этом проведение проверки в отношении сделки, совершенной в налоговый период, не препятствует проведению выездных и (или) камеральных налоговых проверок, налогового мониторинга за этот же налоговый период.\n\n(Пункт в редакции Федерального закона от 08.06.2015 № 150-ФЗ)\n\nО принятии указанного решения федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомляет налогоплательщика в течение трех дней со дня его принятия.\n\nОснования и порядок продления срока проведения проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае необходимости получения информации от иностранных государственных органов, проведения экспертиз и (или) перевода на русский язык документов, представленных налогоплательщиком на иностранном языке, срок проведения проверки может быть продлен дополнительно на срок, не превышающий шесть месяцев, а в случае, если проверка была продлена для получения информации от иностранных государственных органов и в течение шести месяцев федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не смог получить запрашиваемую информацию, срок продления указанной проверки может быть увеличен на три месяца.\n\nКопия решения о продлении срока проведения проверки направляется налогоплательщику в течение трех дней со дня его принятия.\n\nЕсли для определения сопоставимости коммерческих и (или) финансовых условий контролируемых сделок с условиями сопоставляемых сделок между лицами, не являющимися взаимозависимыми, налогоплательщик применил методы, указанные в пункте 1 статьи 1057 настоящего Кодекса, или их комбинацию, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при осуществлении налогового контроля в связи с осуществлением сделок между взаимозависимыми лицами применяет метод (комбинацию методов), примененный (примененную) налогоплательщиком.\n\nПрименение иного метода (комбинации методов) возможно в том случае, если федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, докажет, что метод (комбинация методов), примененный (примененная) налогоплательщиком, исходя из условий совершения контролируемой сделки не позволяет определить сопоставимость коммерческих и (или) финансовых условий контролируемой сделки с условиями сопоставляемых сделок между лицами, не являющимися взаимозависимыми.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе применять в ходе налогового контроля в связи с совершением сделок иные методы, не предусмотренные настоящим разделом.\n\nНалогоплательщик, обратившийся в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о заключении соглашения о ценообразовании для целей налогообложения в отношении внешнеторговой сделки, хотя бы одна сторона которой является налоговым резидентом иностранного государства, с которым заключен договор (соглашение) об избежании двойного налогообложения, обязан обеспечивать в течение 10 лет сохранность данных бухгалтерского и налогового учета и других документов, необходимых для исчисления и уплаты налогов, указанных в пункте 4 статьи 1053 настоящего Кодекса, при исчислении которых учитывались доходы (расходы) по соответствующей сделке.\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nИстребование документов в соответствии с настоящим пунктом производится в порядке, аналогичном порядку истребования документов, установленному статьей 931 настоящего Кодекса, и в сроки, установленные настоящим пунктом. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nИстребуемые в соответствии с настоящим пунктом документы (информация) представляются лицами, указанными в абзаце первом настоящего пункта, в течение 10 дней со дня получения соответствующего требования. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nЕсли истребуемые документы (информация) не могут быть представлены в установленный настоящим пунктом срок, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при получении от лица, у которого истребованы документы (информация), уведомления о невозможности представления в установленный срок документов (информации) и о сроке (при необходимости), в течение которого эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации). Указанное уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nСправка о проведенной проверке вручается лицу, в отношении которого проводилась такая проверка, или его представителю под расписку или передается иным способом, свидетельствующим о дате ее получения.\n\nВ случае, если налогоплательщик (его представитель) уклоняется от получения справки о проведенной проверке, указанная справка направляется налогоплательщику по почте заказным письмом.\n\nВ случае направления справки о проведенной проверке по почте заказным письмом датой ее вручения считается шестой день считая с даты отправки заказного письма.\n\nФорма акта проверки и требования к его составлению устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n10. Акт проверки подписывается должностными лицами, проводившими проверку, и лицом, в отношении которого проводилась такая проверка, или его представителем.\n\nОб отказе лица, в отношении которого проводилась проверка, или его представителя подписать акт проверки в этом акте делается соответствующая запись.\n\n12. Акт проверки в течение пяти дней с даты этого акта должен быть вручен лицу, в отношении которого проводилась проверка, или его представителю под расписку или передан иным способом, свидетельствующим о дате его получения указанным лицом (его представителем).\n\nВ случае, если лицо, в отношении которого проводилась проверка, или его представитель уклоняются от получения акта проверки, этот факт отражается в акте проверки и акт проверки направляется по почте заказным письмом по месту нахождения организации или месту жительства физического лица.\n\nВ случае направления акта проверки по почте заказным письмом датой вручения этого акта считается шестой день считая с даты отправки заказного письма.\n\n13. Лицо, в отношении которого проводилась проверка, или его представитель в случае несогласия с фактами, изложенными в акте проверки, а также с выводами и предложениями проверяющих вправе в течение 20 дней со дня получения акта представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, письменные возражения по указанному акту в целом или по его отдельным положениям. При этом указанное лицо вправе приложить к письменным возражениям или в согласованный срок передать в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, документы (их заверенные копии), подтверждающие обоснованность возражений.\n\n14. Рассмотрение акта, других материалов проверки и письменных возражений по акту, которые представлены налогоплательщиком, а также принятие решения по результатам проверки осуществляется в порядке, аналогичном порядку рассмотрения материалов налоговой проверки, предусмотренному статьей 101 настоящего Кодекса.\n\n15. Материалы и сведения, полученные федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, при осуществлении мероприятий налогового контроля в связи с совершением сделки между взаимозависимыми лицами, могут быть использованы при проведении проверки иных лиц, являющихся участниками этой же контролируемой сделки.","article_title":"Статья 105.17. Проверка федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a21f74519fa6e93f84f7f0ced54c657be7ab4f0df6bc174e112e6dd41c3e6ffc"},{"code_id":"NK_RF","article_number":"105.18","version_date":"2000-07-31","article_text":"1. Российскими организациями - налогоплательщиками, являющимися другими сторонами контролируемой сделки (далее - другая сторона сделки), при исчислении налогов, указанных в пункте 4 статьи 1053 настоящего Кодекса, могут быть применены цены, на основании которых федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, осуществлена корректировка налоговой базы и суммы налога (в случае доначисления налога по итогам проверки федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами исходя из оценки результатов сделки с учетом рыночных цен) либо на основании которых налогоплательщиками осуществлена корректировка налоговой базы и суммы налога (убытка) (в случае, предусмотренном пунктом 6 статьи 1053 настоящего Кодекса).\n\nПрименение таких цен в целях настоящего Кодекса признается симметричной корректировкой.\n\nСимметричные корректировки осуществляются в порядке, установленном настоящей статьей.\n\n2. Другая сторона сделки вправе применять симметричную корректировку в случае:\n\n1) если решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающее доначисление налога или уменьшение суммы убытка, исполнено налогоплательщиком, в отношении которого было вынесено такое решение. Право на симметричные корректировки в указанном случае возникает со дня получения уведомления о возможности симметричных корректировок, выдача (направление) которого осуществляется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в порядке, предусмотренном пунктами 5 - 9 настоящей статьи;\n\n2) если налогоплател\n\nьщик, самостоятельно осуществивший корректировку налоговой базы и суммы налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, представил налоговую декларацию, в которой отражена соответствующая корректировка, и погасил сумму недоимки, возникшей в результате такой корректировки (при ее наличии).\n\n3. Для целей применения симметричных корректировок не осуществляются корректировки регистров налогового учета и первичных документов. Симметричные корректировки отражаются:\n\n1) в случае, если право на такие корректировки возникло у другой стороны сделки в соответствии с подпунктом 1 пункта 2 настоящей статьи, - в налоговых декларациях по налогам, указанным в пункте 4 статьи 1053 настоящего Кодекса, представленных по итогам налогового периода, в котором другой стороной сделки получено уведомление о возможности симметричных корректировок;\n\n2) в случае, если право на такие корректировки возникло у другой стороны сделки в соответствии с подпунктом 2 пункта 2 настоящей статьи, - в налоговых декларациях по налогам, указанным в пункте 4 статьи 1053 настоящего Кодекса, представленных по итогам налогового периода, за который налогоплательщик самостоятельно осуществил корректировку налоговой базы и суммы налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nФорма уведомления о возможности симметричных корректировок и порядок его выдачи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае принятия федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по итогам проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, он уведомляет другую сторону сделки о возможности симметричных корректировок путем выдачи или направления по почте заказным письмом либо в электронной форме по телекоммуникационным каналам связи соответствующего уведомления в течение одного месяца со дня исполнения такого решения.\n\nТечение срока выдачи или направления другой стороне сделки уведомления о возможности симметричных корректировок приостанавливается при получении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, информации об обжаловании в судебном порядке решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, на основе которого проводятся симметричные корректировки. Такое приостановление действует до дня вступления в силу соответствующего судебного акта.\n\nВ случае нарушения федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, срока выдачи или направления другой стороне сделки уведомления о возможности симметричных корректировок, предусмотренного настоящим пунктом, на сумму налога, подлежащую возврату налогоплательщику по результатам симметричной корректировки, начисляются проценты, подлежащие уплате указанному налогоплательщику за каждый календарный день начиная со дня окончания срока, установленного настоящим пунктом для выдачи или направления налогоплательщику соответствующего уведомления. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nПроцентная ставка принимается равной ставке рефинансирования Центрального банка Российской Федерации, действовавшей в период нарушения срока направления соответствующего уведомления федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nК заявлению о выдаче уведомления о возможности симметричных корректировок должны быть приложены копии документов, подтверждающих информацию о вынесенном в отношении налогоплательщика решении о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающем доначисление налога или уменьшение суммы убытка, и его исполнении.\n\n1) выдать уведомление о возможности симметричных корректировок;\n\n2) отказать в выдаче уведомления о возможности симметричных корректировок;\n\n3) информировать о приостановлении срока выдачи уведомления о возможности симметричных корректировок в случае обжалования решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, на основании которого проводятся симметричные корректировки.\n\n1) несоблюдения порядка подачи заявления о выдаче уведомления о возможности симметричных корректировок;\n\n2) неподтверждения указанной в заявлении информации;\n\n3) представления налогоплательщиком в период рассмотрения заявления о выдаче уведомления о возможности симметричных корректировок уточненной налоговой декларации, в которой изменены налоговая база и сумма налога (убытка).\n\nО принятии решения, предусмотренного подпунктом 2 или 3 пункта 7 настоящей статьи, другой стороне сделки, обратившейся с заявлением о выдаче уведомления о возможности симметричных корректировок, сообщается не позднее одного дня со дня принятия соответствующего решения.\n\nФорма решений, указанных в пункте 7 настоящей статьи, и порядок их принятия утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если другой стороной сделки не представлены документы (сведения), указанные в настоящем пункте (либо представлены документы, содержащие недостоверные сведения), и (или) не выполнены условия, указанные в подпункте 2 пункта 2 настоящей статьи, сумма налога (убытка) подлежит восстановлению, при этом сумма налога подлежит уплате в бюджет в установленном порядке с взысканием с другой стороны сделки соответствующих сумм налоговых санкций и пеней.\n\nВеличина, на которую изменен размер налоговой базы (убытка) в результате симметричной корректировки, произведенной по основаниям, предусмотренным подпунктами 1 и 2 пункта 2 настоящей статьи, должна соответствовать величине, на которую изменен размер налоговой базы (убытка) в случаях, предусмотренных пунктами 5 и 6 статьи 1053 настоящего Кодекса.\n\nВ случае, если налогоплательщик, являющийся другой стороной контролируемой сделки, осуществил корректировку в соответствии с налоговой декларацией, представленной налогоплательщиком в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, а впоследствии этим налогоплательщиком была представлена уточненная налоговая декларация с уменьшением налоговой базы и (или) суммы налога, налогоплательщик, являющийся другой стороной контролируемой сделки, должен произвести соответствующую обратную корректировку.\n\nОбратные корректировки производятся другой стороной сделки на основании уведомления о необходимости обратных корректировок, полученного от налогового органа по месту учета другой стороны сделки, в течение одного месяца с даты получения указанного уведомления. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nФорма уведомления о необходимости обратных корректировок и порядок его выдачи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nК уведомлению о необходимости обратных корректировок в связи с изменением (отменой) или признанием недействительным решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, прилагается расчет обратных корректировок, составленный в произвольной форме, а также копия соответствующего судебного акта, отменяющего (изменяющего) или признающего недействительным такое решение или соответствующие судебные акты.\n\nК уведомлению о необходимости обратных корректировок в связи с проведением налогоплательщиком самостоятельно корректировок в соответствии с пунктом 6 статьи 1053 настоящего Кодекса прилагается расчет обратных корректировок, составленный в произвольной форме. В уведомлении указывается дата подачи уточненной налоговой декларации.\n\nНалоговый орган производит возврат суммы денежных средств налогоплательщику, который является стороной контролируемой сделки и в отношении которого было вынесено решение о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающее доначисление налога или уменьшение суммы убытка, или который осуществил самостоятельно корректировку в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, только после проведения обратных корректировок и уплаты налога налогоплательщиком, являющимся другой стороной контролируемой сделки. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Статья в редакции Федерального закона от 08.06.2015 № 150-ФЗ)","article_title":"Статья 105.18. Симметричные корректировки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a50cddedf2a50be856f0e634ec4eeaa2bdf1105b6ccd885984efeb59843e9a53"},{"code_id":"NK_RF","article_number":"105.18-1","version_date":"2000-07-31","article_text":"1. Для целей применения корректировок по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения не осуществляются корректировки регистров налогового учета и первичных документов.\n\nТакие корректировки отражаются в налоговых декларациях по налогам, указанным в подпунктах 1 и 2 пункта 4 статьи 1053 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 105.18-1. Корректировки по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0a7f54ac7d44b7d87cd9e5efcc97e4ef8fef2472946bf28b89add78f6554396"},{"code_id":"NK_RF","article_number":"105.19","version_date":"2000-07-31","article_text":"1) виды и (или) перечни контролируемых сделок и товаров (работ, услуг), в отношении которых заключается соглашение;\n\n2) порядок определения цен и (или) описание и порядок применения методик (формул) ценообразования для целей налогообложения;\n\n3) перечень источников информации, используемых при определении соответствия цен, примененных в сделках, условиям соглашения;\n\n4) срок действия соглашения;\n\n5) перечень, порядок и сроки представления документов, подтверждающих исполнение условий соглашения о ценообразовании.","article_title":"Статья 105.19. Общие положения о соглашении о ценообразовании для целей налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b09490b44b98f9e0ac497723518bc78aaec2d0e46fc2d56c29061a4f961468bf"},{"code_id":"NK_RF","article_number":"105.2","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса доля участия лица в организации определяется в виде суммы выраженных в процентах долей прямого и косвенного участия этого лица в организации.\n\n2. Долей прямого участия лица в организации признается непосредственно принадлежащая такому лицу доля голосующих акций этой организации или непосредственно принадлежащая такому лицу доля в уставном (складочном) капитале (фонде) этой организации, а в случае невозможности определения таких долей - непосредственно принадлежащая такому лицу, являющемуся участником этой организации, доля, определяемая пропорционально общему количеству участников этой организации.\n\nВ случае, если акции (доли в уставном (складочном) капитале (фонде) организации входят в состав активов инвестиционного фонда или негосударственного пенсионного фонда, созданных в соответствии с законодательством Российской Федерации, доля прямого участия в такой организации определяется пропорционально доле участия (доле вносимого имущества во вклад) лиц в таком инвестиционном фонде (негосударственном пенсионном фонде), а в случае невозможности определения такой доли - пропорционально количеству лиц.\n\n3. Долей косвенного участия лица в другой организации признается доля, определяемая в следующем порядке:\n\n1) определяются все последовательности участия лица в организации через прямое участие каждой предыдущей организации (иного лица) в каждой последующей организации соответствующей последовательности;\n\n2) определяются доли прямого участия каждой предыдущей организации (иного лица) в каждой последующей организации соответствующей последовательности;\n\n3) определяются доли косвенного участия одной организации (иного лица) в другой организации каждой последовательности, при этом доля косвенного участия определяется как произведение долей прямого участия первых двух организаций (иных лиц) в последовательности, а при наличии последующего участия путем умножения получившегося произведения на долю следующего прямого участия в последовательности и каждого следующего получившегося произведения на каждую долю следующего прямого участия до последней организации в последовательности;\n\n4) при наличии нескольких последовательностей участия суммируются все доли косвенного участия лица в организации, определенные в соответствии с подпунктом 3 настоящего пункта.\n\n4. При определении доли участия лица в организации не учитывается участие, реализованное посредством владения ценными бумагами, приобретенными в рамках договора репо, заключенного в соответствии с Федеральным законом \"О рынке ценных бумаг\", или операции, признаваемой операцией РЕПО в соответствии с законодательством иностранного государства. При этом в целях определения доли прямого и (или) косвенного участия такие ценные бумаги учитываются у лица, которое является продавцом ценных бумаг по первой части РЕПО, за исключением случаев, когда ценные бумаги, проданные продавцом по первой части РЕПО, были им получены по другой операции РЕПО или операции займа ценными бумагами.\n\nВ случае неисполнения или исполнения не в полном объеме второй части РЕПО определение доли участия лица в организации осуществляется без учета особенностей, установленных настоящим пунктом.\n\n5. При определении доли участия лица в организации не учитывается участие, реализованное посредством владения ценными бумагами, полученными в рамках договора займа ценными бумагами, заключенного в соответствии с законодательством Российской Федерации или законодательством иностранного государства. При этом в целях определения доли прямого и (или) косвенного участия такие ценные бумаги учитываются у лица, которое является кредитором (представляет ценные бумаги в заем), за исключением случаев, когда ценные бумаги, переданные в рамках договора займа ценными бумагами, были получены кредитором по другой операции займа ценными бумагами или операции РЕПО.\n\nВ случае неисполнения или исполнения не в полном объеме обязательств по возврату ценных бумаг по операциям займа ценными бумагами определение доли участия лица в организации осуществляется без учета особенностей, установленных настоящим пунктом.\n\n6. При определении доли участия лица в организации учитывается также участие, осуществляемое с использованием иностранной структуры без образования юридического лица, в случае, если такое лицо признается контролирующим лицом этой структуры. При этом доля такого участия с использованием иностранной структуры без образования юридического лица определяется в порядке, аналогичном порядку определения доли косвенного участия лица в организации, осуществляемого с использованием другой организации, установленному пунктом 3 настоящей статьи, с учетом особенностей, установленных абзацем вторым настоящего пункта.\n\nДля определения доли косвенного участия лица в организации при наличии более одного контролирующего лица иностранной структуры без образования юридического лица доля каждого из контролирующих лиц в такой организации определяется пропорционально вкладу каждого контролирующего лица в имущество, переданное этой структуре. В случае невозможности определения размера вклада в имущество, переданное такой структуре, доли всех контролирующих лиц в целях определения доли их участия в организации признаются равными, а их размер определяется исходя из количества контролирующих лиц такой структуры.\n\nПравила, предусмотренные настоящим пунктом, применяются также при определении доли участия в организации, осуществляемого с использованием иностранного юридического лица, для которого в соответствии с его личным законом не предусмотрено участие (отсутствует уставный капитал или фонд).\n\n7. Дополнительные обстоятельства при определении доли участия лица в организации учитываются в судебном порядке.\n\n(Статья в редакции Федерального закона от 15.02.2016 № 32-ФЗ)","article_title":"Статья 105.2. Порядок определения доли участия лица в организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e2ddf4f2ceb776100a0fc68878a3639a6ee96bf1243d908736930e3c53f96f1"},{"code_id":"NK_RF","article_number":"105.20","version_date":"2000-07-31","article_text":"1. Сторонами соглашения о ценообразовании являются налогоплательщик и федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в лице его руководителя (заместителя руководителя), если иное не предусмотрено пунктом 2 настоящей статьи.\n\nПредусмотренное настоящим пунктом соглашение о ценообразовании основывается на взаимном соглашении федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, и уполномоченного органа исполнительной власти иностранного государства, достигнутом по результатам проведенной с учетом положений главы 203 настоящего Кодекса взаимосогласительной процедуры, предусмотренной международным договором Российской Федерации по вопросам налогообложения. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nПри заключении соглашения о ценообразовании, изменении условий и проведении проверки исполнения условий соглашения о ценообразовании в порядке, установленном соответственно статьями 10522, 10523 настоящего Кодекса, общие интересы группы налогоплательщиков может представлять одна организация из группы налогоплательщиков, полномочия которой подтверждаются доверенностями, выданными в порядке, установленном законодательством Российской Федерации.","article_title":"Статья 105.20. Стороны соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b44a225990c0d59c39b73b696010a6277a7ab9c94ef0dcda68c1056edbc601cc"},{"code_id":"NK_RF","article_number":"105.21","version_date":"2000-07-31","article_text":"1. Соглашение о ценообразовании может быть заключено по одной либо нескольким сделкам (группе однородных сделок), имеющим один и тот же предмет, в отношении следующих периодов или их совокупности:\n\n1) в отношении календарного года, в котором впервые представлено заявление о заключении соглашения о ценообразовании;\n\n2) в отношении двух календарных лет, предшествующих периоду, указанному в подпункте 1 настоящего пункта;\n\n3) в отношении двух календарных лет, следующих за периодом, указанным в подпункте 1 настоящего пункта.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2. Налогоплательщик при соблюд\n\nении им всех условий соглашения о ценообразовании вправе обратиться в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о продлении срока действия соглашения о ценообразовании.\n\n3. Соглашение о ценообразовании может быть продлено по соглашению сторон не более чем на два года в порядке, предусмотренном статьей 10522 настоящего Кодекса.\n\n4. Соглашение о ценообразовании вступает в силу с 1 января календарного года, следующего за годом, в котором оно было подписано, если иное не предусмотрено непосредственно указанным соглашением.","article_title":"Статья 105.21. Срок действия соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7ffb4e714e503c5c0abba7944e0e3f4fce18afe63437e38a2ec3ea48b8301c2"},{"code_id":"NK_RF","article_number":"105.22","version_date":"2000-07-31","article_text":"1. К заявлению налогоплательщика о заключении соглашения о ценообразовании, представленному налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, прилагаются:\n\n1) проект соглашения о ценообразовании;\n\n2) документы о деятельности налогоплательщика, связанной с контролируемыми сделками, а также о контролируемых сделках, в отношении которых налогоплательщиком предлагается заключить соглашение о ценообразовании;\n\n3) копии учредительных документов налогоплательщика;\n\n4) (Подпункт утратил силу - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n6) бухгалтерская (финансовая) отчетность налогоплательщика за последний отчетный период; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n61) документы, подтверждающие совершение налогоплательщиком сделок, которые признаются контролируемыми сделками в соответствии с пунктом 1 статьи 10514 настоящего Кодекса и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса, и сумма доходов (расходов) по которым за календарный год составляет не менее 2 миллиардов рублей. Положения настоящего подпункта не распространяются на налогоплательщиков, отнесенных в соответствии со статьей 83 настоящего Кодекса к категории крупнейших налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n7) документ, подтверждающий уплату заявителем государственной пошлины за рассмотрение федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, заявления о заключении соглашения о ценообразовании;\n\n8) иные документы, содержащие информацию, имеющую значение при заключении соглашения о ценообразовании.\n\n2. Документы, перечисленные в пункте 1 настоящей статьи, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в произвольной форме, если иная форма не установлена законодательством Российской Федерации.\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе запрашивать у налогоплательщика другие, не предусмотренные пунктом 1 настоящей статьи документы, необходимые для целей соглашения о ценообразовании.\n\nУказанные документы должны быть представлены налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в течение 10 дней со дня получения соответствующего запроса федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nЕсли запрашиваемые документы не могут быть представлены в установленный настоящим пунктом срок, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при получении от налогоплательщика, у которого запрошены документы, уведомления о невозможности представления в установленный срок документов и о сроке (при необходимости), в течение которого эти документы могут быть представлены, вправе продлить срок представления этих документов. Указанное уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n31. Налогоплательщик вместе с заявлением о заключении соглашения о ценообразовании, представляемым в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в соответствии с пунктом 2 статьи 10520 настоящего Кодекса, представляет сведения о подаче контрагентом налогоплательщика в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого он является, аналогичного заявления в целях заключения такого соглашения, если иное не предусмотрено настоящим пунктом.\n\nВ случае, если на дату представления налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, заявления о заключении соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого является контрагент налогоплательщика, не подано аналогичное заявление в целях заключения соглашения о ценообразовании, после подачи контрагентом налогоплательщика указанного заявления налогоплательщик должен в письменной форме сообщить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, о подаче контрагентом налогоплательщика указанного заявления. Соответствующие сведения представляются налогоплательщиком в срок не позднее шести месяцев со дня представления им заявления о заключении соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n4. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, рассматривает заявление и другие документы, представленные налогоплательщиком в соответствии с пунктами 1 - 3 настоящей статьи, в срок не более шести месяцев со дня получения заявления, если иное не предусмотрено настоящим пунктом.\n\nЗаявление и другие документы, представленные налогоплательщиком в целях заключения соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса, рассматриваются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в срок не более 24 месяцев со дня получения заявления, а в предусмотренном пунктом 31 настоящей статьи случае - со дня получения от налогоплательщика сведений о подаче его контрагентом заявления в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого он является, в целях заключения такого соглашения о ценообразовании.\n\nСрок рассмотрения заявления и других документов, представленных налогоплательщиком в соответствии с пунктом 1 настоящей статьи в целях заключения соглашения о ценообразовании, предусмотренного пунктом 2 статьи 10520 настоящего Кодекса, приостанавливается на период представления уполномоченным органом исполнительной власти иностранного государства документов и (или) информации в соответствии с запросом, направленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в рамках проведения с учетом положений главы 203 настоящего Кодекса взаимосогласительной процедуры, предусмотренной международным договором Российской Федерации по вопросам налогообложения.\n\nСрок рассмотрения представленных налогоплательщиком документов может быть продлен до девяти месяцев в случае, указанном в абзаце первом настоящего пункта, а в случае, предусмотренном абзацем вторым настоящего пункта, - до 27 месяцев.\n\nОснования и порядок продления срока рассмотрения представленных налогоплательщиком документов устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n5. По результатам рассмотрения документов, представленных налогоплательщиком в соответствии с пунктами 1 - 3 настоящей статьи, федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, принимается одно из следующих решений:\n\n1) решение о заключении соглашения о ценообразовании;\n\n2) мотивированное решение об отказе от заключения такого соглашения;\n\n3) решение о необходимости доработки проекта соглашения, в котором федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, предлагает налогоплательщику доработать в соответствии с требованиями настоящего Кодекса и повторно представить проект соглашения о ценообразовании и документы, указанные в подпункте 2 пункта 1 настоящей статьи.\n\n1) государственная пошлина, предусмотренная подпунктом 133 пункта 1 статьи 33333 настоящего Кодекса, не взимается; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n2) федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, решение принимается в течение трех месяцев.\n\n1) непредставление или представление не в полном объеме документов, предусмотренных пунктом 1 настоящей статьи;\n\n2) неуплата или неполная уплата государственной пошлины;\n\n3) мотивированный вывод о том, что в результате применения предложенного налогоплательщиком в проекте соглашения о ценообразовании порядка определения цен и (или) методов ценообразования не будет обеспечиваться исполнение положений пункта 1 статьи 1053 настоящего Кодекса;\n\n4) недостижение взаимного соглашения с уполномоченным органом исполнительной власти иностранного государства в целях заключения предусмотренного пунктом 2 статьи 10520 настоящего Кодекса соглашения о ценообразовании; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n5) непредставление документов (сведений), предусмотренных пунктами 3 и 31 настоящей статьи, в порядке и сроки, которые установлены настоящей статьей; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n6) несогласие налогоплательщика с решением о необходимости доработки проекта соглашения о ценообразовании (в том числе в форме непредставления доработанного проекта соглашения о ценообразовании в срок, установленный пунктом 61 настоящей статьи); (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n7) несогласие налогоплательщика с решением о заключении соглашения о ценообразовании, которое выразилось в отказе налогоплательщика от подписания соглашения о ценообразовании (в том числе в форме неявки налогоплательщика (его представителя) для подписания соглашения о ценообразовании в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов). (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)","article_title":"Статья 105.22. Порядок заключения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9417a72edb8ff8a40e0e5a718d1954c6c09ecf112555c1e7812fad62532a5437"},{"code_id":"NK_RF","article_number":"105.23","version_date":"2000-07-31","article_text":"1. Проверка исполнения налогоплательщиком соглашения о ценообразовании осуществляется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в соответствии с порядком, предусмотренным главой 145 настоящего Кодекса.","article_title":"Статья 105.23. Проверка исполнения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d772f8f0ac88e113ef0261f0bec312d2c0a9846368e32d3c49ea60996409464f"},{"code_id":"NK_RF","article_number":"105.24","version_date":"2000-07-31","article_text":"1. Соглашение о ценообразовании прекращается по истечении срока его действия либо может быть прекращено до истечения такого срока в случаях, предусмотренных настоящей статьей.\n\n2. Действие соглашения о ценообразовании прекращается досрочно по решению руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, при нарушении налогоплательщиком соглашения о ценообразовании в течение срока его действия, повлекшем за собой неполную уплату налогов и выявленном в ходе проведения проверки в порядке, предусмотренном главой 145 настоящего Кодекса.\n\nСоглашение о ценообразовании также может быть расторгнуто досрочно по соглашению сторон или по решению суда.\n\n3. Решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о прекращении соглашения о ценообразовании, вручается налогоплательщику (его представителю) под расписку или передается иным способом, свидетельствующим о дате его получения налогоплательщиком (его представителем), либо направляется налогоплательщику по почте заказным письмом в течение пяти дней со дня принятия соответствующего решения.\n\nРешение о прекращении соглашения о ценообразовании, направленное налогоплательщику по почте заказным письмом, считается полученным по истечении шести дней со дня направления такого заказного письма.\n\nКопия указанного решения в те же сроки направляется в налоговый орган по месту учета этого налогоплательщика в качестве крупнейшего налогоплательщика.\n\n4. Решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о прекращении соглашения о ценообразовании может быть обжаловано налогоплательщиком в арбитражный суд в порядке, установленном арбитражным процессуальным законодательством Российской Федерации.\n\n5. Уплата суммы налога, пеней и штрафа осуществляется только в случае, если прекращение соглашения о ценообразовании вследствие неисполнения (нарушения) его условий повлекло занижение суммы налога.","article_title":"Статья 105.24. Порядок прекращения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8591c6a3e4b35f65b057332fb487abbc98142beea3f56c69138e4b8b79c5a122"},{"code_id":"NK_RF","article_number":"105.25","version_date":"2000-07-31","article_text":"1. Условия соглашения о ценообразовании остаются неизменными в случае изменения законодательства о налогах и сборах в части регулирования отношений, возникающих при заключении соглашения о ценообразовании, внесении в него изменений и прекращении его действия.\n\n2. В случае иных изменений законодательства Российской Федерации о налогах и сборах и законодательства Российской Федерации о таможенном деле, влияющих на деятельность налогоплательщика, стороны соглашения имеют право внести в текст соглашения о ценообразовании соответствующие изменения.\n\n(Дополнение разделом - Федеральный закон от 04.11.2014 № 348-ФЗ)","article_title":"Статья 105.25. Стабильность условий соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2fe66a028c16fb3ff376d044cf4411ab89d8bb01f93de952d387ea24496bf8cf"}]$law7d0050$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
